import React from 'react';
import Icon from '../../../components/AppIcon';

const VerificationProcess = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-gradient-to-br from-[var(--color-primary)]/5 to-[var(--color-secondary)]/5">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-success)]/10 rounded-full mb-4">
            <Icon name="CheckCircle2" size={20} color="var(--color-success)" />
            <span className="text-sm font-medium text-[var(--color-success)]">Verification Process</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {data.steps?.map((item, index) => (
            <div key={index} className="relative bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 group">
              <div className="absolute top-4 right-4 text-6xl md:text-7xl font-bold text-[var(--color-primary)]/5 group-hover:text-[var(--color-primary)]/10 transition-colors" style={{ fontFamily: 'var(--font-headline)' }}>
                {item?.step}
              </div>

              <div className="relative">
                <div className="w-12 h-12 md:w-14 md:h-14 rounded-xl bg-primary flex items-center justify-center mb-4 md:mb-6 group-hover:scale-110 transition-transform">
                  <Icon name={item?.icon} size={24} className="text-primary-foreground" />
                </div>

                <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-3" style={{ fontFamily: 'var(--font-headline)' }}>
                  {item?.title}
                </h3>

                <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                  {item?.description}
                </p>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12 md:mt-16 bg-[var(--color-card)] rounded-2xl p-6 md:p-8 lg:p-10 shadow-[var(--shadow-card)]">
          <div className="flex flex-col lg:flex-row items-start lg:items-center gap-6">
            <div className="w-16 h-16 md:w-20 md:h-20 rounded-xl bg-gradient-to-br from-[var(--color-success)] to-[var(--color-secondary)] flex items-center justify-center flex-shrink-0">
              <Icon name="BadgeCheck" size={36} color="#FFFFFF" />
            </div>
            <div className="flex-1">
              <h3 className="text-xl md:text-2xl font-bold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                {data.badgeTitle}
              </h3>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                {data.badgeDescription}
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default VerificationProcess;