import React from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';


const ImpactMetrics = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-[var(--color-card)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-accent)]/10 rounded-full mb-4">
            <Icon name="BarChart3" size={20} color="var(--color-accent)" />
            <span className="text-sm font-medium text-[var(--color-accent)]">Our Impact</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8 mb-16 md:mb-20">
          {data.metrics?.map((metric, index) => (
            <div key={index} className="bg-[var(--color-background)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 group">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 md:w-14 md:h-14 rounded-xl flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform" style={{ backgroundColor: `${metric?.color}15` }}>
                  <Icon name={metric?.icon} size={24} color={metric?.color} />
                </div>
                <div className="flex-1">
                  <div className="text-3xl md:text-4xl font-bold mb-1" style={{ fontFamily: 'var(--font-headline)', color: metric?.color }}>
                    {metric?.value}
                  </div>
                  <div className="text-base md:text-lg font-semibold text-[var(--color-primary)] mb-1">
                    {metric?.label}
                  </div>
                  <div className="text-sm text-[var(--color-muted-foreground)]">
                    {metric?.description}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mb-12 md:mb-16">
          <h3 className="text-xl md:text-2xl lg:text-3xl font-bold text-[var(--color-primary)] text-center mb-8 md:mb-12" style={{ fontFamily: 'var(--font-headline)' }}>
            Success Stories from Our Community
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
            {data.testimonials?.map((testimonial, index) => (
              <div key={index} className="bg-[var(--color-background)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300">
                <div className="flex items-center gap-4 mb-4">
                  <div className="w-14 h-14 md:w-16 md:h-16 rounded-full overflow-hidden flex-shrink-0">
                    <Image
                      src={testimonial?.image}
                      alt={testimonial?.imageAlt || testimonial?.author}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div>
                    <div className="font-semibold text-[var(--color-primary)]">{testimonial?.author}</div>
                    <div className="text-sm text-[var(--color-muted-foreground)]">{testimonial?.role}</div>
                  </div>
                </div>

                <div className="mb-4">
                  <Icon name="Quote" size={24} color="var(--color-accent)" className="opacity-50" />
                </div>

                <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed italic">
                  "{testimonial?.quote}"
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default ImpactMetrics;