import React from 'react';
import Icon from '../../../components/AppIcon';

const DisclaimerSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-gradient-to-br from-[var(--color-muted)]/20 to-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-error)]/10 rounded-full mb-4">
            <Icon name="FileText" size={20} color="var(--color-error)" />
            <span className="text-sm font-medium text-[var(--color-error)]">Important Disclaimers</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8 mb-12 md:mb-16">
          {data.items?.map((disclaimer, index) => (
            <div key={index} className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] border-2 border-[var(--color-border)] hover:border-[var(--color-primary)]/20 transition-all duration-300">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 md:w-14 md:h-14 rounded-xl bg-[var(--color-error)]/10 flex items-center justify-center flex-shrink-0">
                  <Icon name={disclaimer?.icon} size={24} color="var(--color-error)" />
                </div>
                <h3 className="text-lg md:text-xl font-bold text-[var(--color-primary)] flex-1" style={{ fontFamily: 'var(--font-headline)' }}>
                  {disclaimer?.title}
                </h3>
              </div>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                {disclaimer?.content}
              </p>
            </div>
          ))}
        </div>

        {data.commitment && (
          <div className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 lg:p-10 shadow-[var(--shadow-card)] border-2 border-[var(--color-primary)]/20">
            <div className="flex flex-col lg:flex-row items-start gap-6">
              <div className="w-16 h-16 md:w-20 md:h-20 rounded-xl bg-gradient-to-br from-[var(--color-primary)] to-[var(--color-secondary)] flex items-center justify-center flex-shrink-0">
                <Icon name="CheckCircle2" size={36} color="#FFFFFF" />
              </div>
              <div className="flex-1">
                <h3 className="text-xl md:text-2xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
                  {data.commitment.title}
                </h3>
                <div className="space-y-4">
                  {data.commitment.items?.map((item, idx) => (
                    <div key={idx} className="flex items-start gap-3">
                      <Icon name={item.icon || "Check"} size={20} color="var(--color-success)" className="flex-shrink-0 mt-1" />
                      <p className="text-sm md:text-base text-[var(--color-foreground)]">
                        <strong>{item.title}:</strong> {item.content}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="mt-8 md:mt-12 text-center">
          <p className="text-sm text-[var(--color-muted-foreground)] mb-4">
            Last updated: January 23, 2026
          </p>
          <p className="text-sm text-[var(--color-muted-foreground)]">
            Questions about our disclaimers or policies? <a href="/contact" className="text-[var(--color-primary)] hover:underline font-medium">Contact our team</a>
          </p>
        </div>
      </div>
    </section>
  );
};

export default DisclaimerSection;