export const addOpportunityAsync = createAsyncThunk(
  'content/addOpportunity',
  async (opportunity, { rejectWithValue }) => {
    try {
      const dbPayload = {
        ...opportunity,
        image_alt: opportunity.imageAlt || opportunity.title,
        organization_logo: opportunity.organizationLogo,
        short_description: opportunity.shortDescription,
        detailed_description: opportunity.detailedDescription,
        funding_type: opportunity.fundingType,
        application_link: opportunity.applicationLink,
        benefits_list: opportunity.benefitsList,
        requirements_list: opportunity.requirementsList,
        process_list: opportunity.processList,
        duration: opportunity.duration,
        education_level: opportunity.educationLevel,
        eligibility: opportunity.eligibility,
        language: opportunity.language,
      };

      delete dbPayload.daysLeft;
      delete dbPayload.imageAlt;
      delete dbPayload.organizationLogo;
      delete dbPayload.shortDescription;
      delete dbPayload.detailedDescription;
      delete dbPayload.fundingType;
      delete dbPayload.applicationLink;
      delete dbPayload.benefitsList;
      delete dbPayload.requirementsList;
      delete dbPayload.processList;
      delete dbPayload.educationLevel;
      delete dbPayload._fromSubmissionId;

      const newOpp = await supabaseService.addOpportunity(dbPayload);

      return {
        ...newOpp,
        daysLeft: calculateDaysLeft(newOpp.deadline),
        imageAlt: newOpp.image_alt,
        organizationLogo: newOpp.organization_logo,
        shortDescription: newOpp.short_description,
        detailedDescription: newOpp.detailed_description,
        fundingType: newOpp.funding_type,
        applicationLink: newOpp.application_link,
        benefitsList: newOpp.benefits_list || [],
        requirementsList: newOpp.requirements_list || [],
        processList: newOpp.process_list || [],
        duration: newOpp.duration,
        educationLevel: newOpp.education_level,
        eligibility: newOpp.eligibility,
        language: newOpp.language,
      };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

