import React from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';

const SuccessStories = ({ stories }) => {
  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-success/10 flex items-center justify-center">
          <Icon name="Trophy" size={20} className="text-success" />
        </div>
        <div className="flex-1">
          <h2 className="text-xl md:text-2xl font-bold text-primary">Success Stories</h2>
          <p className="text-xs md:text-sm text-muted-foreground mt-1">
            Real experiences from past recipients
          </p>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
        {stories?.map((story) => (
          <div
            key={story?.id}
            className="bg-background rounded-xl p-4 md:p-6 border-2 border-border hover:border-secondary/50 transition-all duration-300"
          >
            <div className="flex items-start gap-3 md:gap-4 mb-4">
              <Image
                src={story?.avatar}
                alt={story?.avatarAlt}
                className="w-12 h-12 md:w-14 md:h-14 rounded-full object-cover flex-shrink-0"
              />
              <div className="flex-1 min-w-0">
                <h3 className="text-sm md:text-base font-semibold text-foreground truncate">
                  {story?.name}
                </h3>
                <p className="text-xs md:text-sm text-muted-foreground truncate">{story?.title}</p>
                <div className="flex items-center gap-2 mt-1">
                  <div className="flex">
                    {[...Array(5)]?.map((_, i) => (
                      <Icon
                        key={i}
                        name="Star"
                        size={12}
                        className={i < story?.rating ? 'text-accent fill-accent' : 'text-muted'}
                      />
                    ))}
                  </div>
                  <span className="text-xs text-muted-foreground">{story?.year}</span>
                </div>
              </div>
            </div>

            <p className="text-sm md:text-base text-foreground/80 leading-relaxed line-clamp-4">
              {story?.testimonial}
            </p>

            <div className="flex items-center gap-2 mt-4 pt-4 border-t border-border">
              <Icon name="MapPin" size={14} className="text-muted-foreground" />
              <span className="text-xs md:text-sm text-muted-foreground">{story?.location}</span>
            </div>
          </div>
        ))}
      </div>
      <div className="mt-6 p-4 md:p-5 rounded-xl bg-brand-blue/10 border-2 border-brand-blue/20">
        <div className="flex items-start gap-3">
          <Icon name="MessageCircle" size={20} className="text-brand-blue flex-shrink-0 mt-0.5" />
          <div>
            <p className="text-sm md:text-base font-semibold text-brand-blue mb-1">
              Share Your Success Story
            </p>
            <p className="text-xs md:text-sm text-foreground/70">
              Received this opportunity? Help others by sharing your experience with the LUC community.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SuccessStories;