import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const WhatsAppSection = ({ data }) => {
    const [totalLikes, setTotalLikes] = useState('...');

    useEffect(() => {
        let isMounted = true;

        const fetchStats = async () => {
            try {
                const count = await supabaseService.getTotalLikesCount();
                if (isMounted) {
                    console.log("Verified Live Likes Fetched:", count);
                    setTotalLikes(count.toLocaleString() + '+');
                }
            } catch (e) {
                console.error("Error fetching stats:", e);
                if (isMounted) setTotalLikes("500+"); // Fallback
            }
        };

        fetchStats();

        // Valid subscription
        const channel = supabaseService.subscribeToTable('opportunities', () => {
            fetchStats();
        });

        return () => {
            isMounted = false;
            supabaseService.unsubscribe(channel);
        };
    }, []);

    const handleWhatsAppClick = () => {
        window.open(data?.link || 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V', '_blank');
    };

    const stats = [
        { icon: "Bell", value: "24/7", label: "Instant Alerts" },
        { icon: "Heart", value: totalLikes, label: "Loves Received" },
        { icon: "Award", value: "98%", label: "Satisfaction Rate" },
        { icon: "Globe", value: "50+", label: "Countries" }
    ];

    return (
        <section className="bg-gradient-to-r from-[var(--color-success)] to-[#229954] py-12 md:py-16 lg:py-20">
            <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
                <div className="flex flex-col lg:flex-row items-center gap-8 lg:gap-12">
                    <div className="flex-1 text-white text-center lg:text-left">
                        <div className="inline-flex items-center gap-2 bg-white/20 backdrop-blur-sm px-4 py-2 rounded-full mb-4 md:mb-6">
                            <Icon name="Users" size={20} />
                            <span className="text-sm md:text-base font-medium">{data?.memberCount || "15,000+ Active Members"}</span>
                        </div>
                        <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
                            {data?.title || "Join Our WhatsApp Community"}
                        </h2>
                        <p className="text-base md:text-lg lg:text-xl opacity-90 mb-6 md:mb-8 leading-relaxed">
                            {data?.description || "Get instant opportunity alerts, connect with peers, share experiences, and receive personalized guidance from our community mentors."}
                        </p>
                        <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
                            <Button
                                variant="default"
                                size="lg"
                                iconName="MessageCircle"
                                iconPosition="left"
                                onClick={handleWhatsAppClick}
                                className="bg-white text-[var(--color-success)] hover:bg-gray-100"
                            >
                                Join WhatsApp Community
                            </Button>
                        </div>
                    </div>
                    <div className="flex-1 grid grid-cols-2 gap-4 md:gap-6 w-full max-w-md">
                        {stats.map((stat, idx) => (
                            <div key={idx} className="bg-white/10 backdrop-blur-sm rounded-2xl p-4 md:p-6 text-white text-center">
                                <Icon name={stat.icon} size={32} className="mx-auto mb-3 md:mb-4" />
                                <p className="text-2xl md:text-3xl font-bold mb-2">{stat.value}</p>
                                <p className="text-sm md:text-base opacity-80">{stat.label}</p>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default WhatsAppSection;
