import React from 'react';
import Icon from '../../../components/AppIcon';

const HeroSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="relative bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[var(--color-brand-blue)] text-white overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-20 left-10 w-64 h-64 bg-white rounded-full blur-3xl"></div>
        <div className="absolute bottom-20 right-10 w-96 h-96 bg-[var(--color-brand-purple)] rounded-full blur-3xl"></div>
      </div>

      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-16 md:py-24 lg:py-32">
        <div className="text-center max-w-4xl mx-auto">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/10 backdrop-blur-sm rounded-full mb-6 md:mb-8">
            <Icon name="Shield" size={20} />
            <span className="text-sm md:text-base font-medium">{data.badgeText}</span>
          </div>

          <h1 className="text-3xl md:text-4xl lg:text-6xl font-bold mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h1>

          <p className="text-base md:text-lg lg:text-xl text-white/90 mb-8 md:mb-10 leading-relaxed">
            {data.description}
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            {data.stats?.map((stat, idx) => (
              <div key={idx} className="flex items-center gap-3 px-6 py-3 bg-white/10 backdrop-blur-sm rounded-lg min-w-[200px]">
                <Icon name={stat.icon} size={24} />
                <div className="text-left">
                  <div className="text-2xl md:text-3xl font-bold">{stat.value}</div>
                  <div className="text-sm text-white/80">{stat.label}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default HeroSection;