import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import PartnershipModal from './PartnershipModal';
import SubmitOpportunityModal from './SubmitOpportunityModal';

const CTASection = () => {
  const [isPartnershipModalOpen, setIsPartnershipModalOpen] = useState(false);
  const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
  const cta = useSelector((state) => state.content.cta);
  const allOpportunities = useSelector((state) => state.content.allOpportunities);
  const [counts, setCounts] = useState({ scholarships: 0, internships: 0, fellowships: 0, competitions: 0, loading: true });

  useEffect(() => {
    const fetchCounts = async () => {
      try {
        const opportunities = allOpportunities.length > 0 ? allOpportunities : await supabaseService.getOpportunities();
        const getCount = (cat) => opportunities.filter(o => o.category?.toLowerCase().includes(cat)).length;
        setCounts({
          scholarships: getCount('scholarship'),
          internships: getCount('internship'),
          fellowships: getCount('fellowship'),
          competitions: getCount('competition'),
          loading: false
        });
      } catch (error) {
        console.error("Error fetching CTA counts:", error);
      }
    };
    fetchCounts();
  }, [allOpportunities]);

  const discoveryStats = [
    { icon: "GraduationCap", label: `${counts.loading ? '...' : counts.scholarships} Scholarships` },
    { icon: "Briefcase", label: `${counts.loading ? '...' : counts.internships} Internships` },
    { icon: "Award", label: `${counts.loading ? '...' : counts.fellowships} Fellowships` },
    { icon: "Trophy", label: `${counts.loading ? '...' : counts.competitions} Competitions` }
  ];

  // Fallback content if database is empty/loading
  const defaults = {
    whatsapp: {
      title: "Join Our WhatsApp Community",
      description: "Get instant notifications about new opportunities, deadline reminders, and connect with members who share your ambitions. Never miss an opportunity again!",
      buttonText: "Join WhatsApp Channel",
      link: "https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V"
    },
    discovery: {
      title: "Start Your Discovery Journey",
      description: "Explore verified opportunities across scholarships, internships, fellowships, and more. Your dream opportunity is waiting to be discovered!",
      buttonText: "Explore Opportunities"
    },
    partner: {
      title: "Organizations & Institutions",
      description: "Reach ambitious students and professionals. Partner with LUC to amplify your opportunities. Partner with LUC today"
    }
  };

  const content = cta || defaults;

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-gradient-to-br from-[var(--color-background)] to-[var(--color-card)]/30">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* WhatsApp Card */}
          <div className="bg-gradient-to-br from-[var(--color-brand-blue)] to-[var(--color-brand-purple)] rounded-3xl p-8 md:p-12 text-white relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>

            <div className="relative">
              <div className="w-14 h-14 md:w-16 md:h-16 rounded-xl bg-white/20 backdrop-blur-sm flex items-center justify-center mb-6">
                <Icon name="MessageCircle" size={28} color="white" />
              </div>

              <h3 className="text-2xl md:text-3xl font-bold mb-4">
                {content.whatsapp ? content.whatsapp.title : defaults.whatsapp.title}
              </h3>
              <p className="text-sm md:text-base text-white/90 mb-6 leading-relaxed">
                {content.whatsapp ? content.whatsapp.description : defaults.whatsapp.description}
              </p>

              <ul className="space-y-3 mb-8">
                {[
                  "Real-time opportunity alerts",
                  "Exclusive community-only opportunities",
                  "Application tips and success stories",
                  "Direct support from our team"
                ].map((feature, index) => (
                  <li key={index} className="flex items-start gap-3">
                    <div className="w-6 h-6 rounded-full bg-[var(--color-success)] flex items-center justify-center flex-shrink-0 mt-0.5">
                      <Icon name="Check" size={14} color="white" />
                    </div>
                    <span className="text-sm md:text-base">{feature}</span>
                  </li>
                ))}
              </ul>

              <Button
                variant="default"
                size="lg"
                iconName="ExternalLink"
                iconPosition="right"
                className="bg-white text-[var(--color-brand-blue)] hover:bg-white/90 font-semibold"
                fullWidth
                onClick={() => window.open(content.whatsapp?.link || defaults.whatsapp.link, '_blank')}
              >
                {content.whatsapp ? content.whatsapp.buttonText : defaults.whatsapp.buttonText}
              </Button>
            </div>
          </div>

          {/* Discovery Card */}
          <div className="bg-gradient-to-br from-[var(--color-success)] to-[var(--color-secondary)] rounded-3xl p-8 md:p-12 text-white relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>

            <div className="relative">
              <div className="w-14 h-14 md:w-16 md:h-16 rounded-xl bg-white/20 backdrop-blur-sm flex items-center justify-center mb-6">
                <Icon name="Compass" size={28} color="white" />
              </div>

              <h3 className="text-2xl md:text-3xl font-bold mb-4">
                {content.discovery ? content.discovery.title : defaults.discovery.title}
              </h3>
              <p className="text-sm md:text-base text-white/90 mb-6 leading-relaxed">
                {content.discovery ? content.discovery.description : defaults.discovery.description}
              </p>

              <div className="grid grid-cols-2 gap-4 mb-8">
                {discoveryStats.map((item, index) => (
                  <div key={index} className="bg-white/10 backdrop-blur-sm rounded-xl p-4 text-center">
                    <Icon name={item.icon} size={24} color="white" className="mx-auto mb-2" />
                    <p className="text-xs md:text-sm font-semibold">{item.label}</p>
                  </div>
                ))}
              </div>

              <Button
                variant="default"
                size="lg"
                iconName="Search"
                iconPosition="left"
                className="bg-white text-[var(--color-success)] hover:bg-white/90 font-semibold"
                fullWidth
                asChild
              >
                <Link to="/opportunity-discovery">
                  {content.discovery ? content.discovery.buttonText : defaults.discovery.buttonText}
                </Link>
              </Button>
            </div>
          </div>
        </div>

        {/* Partner Section */}
        <div className="mt-12 md:mt-16 bg-[var(--color-card)] rounded-3xl p-8 md:p-12 shadow-[var(--shadow-card)] border border-[var(--color-border)]">
          <div className="max-w-4xl mx-auto text-center">
            <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-accent)]/10 text-[var(--color-accent)] rounded-full mb-6">
              <Icon name="Sparkles" size={20} />
              <span className="text-sm md:text-base font-semibold">Partner With Us</span>
            </div>

            <h3 className="text-2xl md:text-3xl font-bold text-[var(--color-primary)] mb-4">
              {content.partner ? content.partner.title : defaults.partner.title}
            </h3>
            <p className="text-sm md:text-base text-[var(--color-muted-foreground)] mb-8 leading-relaxed">
              {content.partner ? content.partner.description : defaults.partner.description}
            </p>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Button
                variant="default"
                size="lg"
                iconName="Building2"
                iconPosition="left"
                className="bg-[var(--color-primary)] hover:bg-[var(--color-trust-builder)]"
                onClick={(e) => {
                  e.preventDefault();
                  setIsPartnershipModalOpen(true);
                }}
              >
                Become a Partner
              </Button>
              <Button
                variant="outline"
                size="lg"
                iconName="Upload"
                iconPosition="left"
                onClick={(e) => {
                  e.preventDefault();
                  setIsSubmitModalOpen(true);
                }}
              >
                Submit Opportunity
              </Button>
            </div>
          </div>
        </div>
      </div>
      <PartnershipModal
        isOpen={isPartnershipModalOpen}
        onClose={() => setIsPartnershipModalOpen(false)}
      />
      <SubmitOpportunityModal
        isOpen={isSubmitModalOpen}
        onClose={() => setIsSubmitModalOpen(false)}
      />
    </section>
  );
};

export default CTASection;