import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';

const UserManagementPanel = ({ users, onUpdateRole, onSuspend, onDelete, onRefresh, isLoading }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');

  const roleOptions = [
    { value: 'all', label: 'All Roles' },
    { value: 'admin', label: 'Admin' },
    { value: 'moderator', label: 'Moderator' },
    { value: 'contributor', label: 'Contributor' },
    { value: 'user', label: 'User' }
  ];

  const filteredUsers = users?.filter(user => {
    const matchesSearch = user?.name?.toLowerCase()?.includes(searchQuery?.toLowerCase()) ||
      user?.email?.toLowerCase()?.includes(searchQuery?.toLowerCase());
    const matchesRole = roleFilter === 'all' || user?.role === roleFilter;
    return matchesSearch && matchesRole;
  });

  const getRoleBadge = (role) => {
    const roleConfig = {
      admin: { bg: 'bg-error/10', text: 'text-error', label: 'Admin' },
      moderator: { bg: 'bg-warning/10', text: 'text-warning', label: 'Moderator' },
      contributor: { bg: 'bg-secondary/10', text: 'text-secondary', label: 'Contributor' },
      user: { bg: 'bg-muted', text: 'text-muted-foreground', label: 'User' }
    };
    const config = roleConfig?.[role] || roleConfig?.user;
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${config?.bg} ${config?.text}`}>
        {config?.label}
      </span>
    );
  };

  return (
    <div className="bg-card rounded-2xl shadow-[0_4px_12px_rgba(27,54,93,0.08)]">
      <div className="p-4 md:p-6 border-b border-border">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl md:text-2xl font-bold text-foreground">User Management</h2>
          <Button
            variant="ghost"
            size="sm"
            iconName="RotateCw"
            onClick={onRefresh}
            loading={isLoading}
            className={`shrink-0 h-10 w-10 p-0 rounded-full hover:bg-muted ${isLoading ? 'opacity-50' : ''}`}
            title="Refresh User Data"
          />
        </div>

        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 w-full">
            <Input
              type="search"
              placeholder="Search users..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e?.target?.value)}
            />
          </div>
          <div className="w-full md:w-48">
            <Select
              options={roleOptions}
              value={roleFilter}
              onChange={setRoleFilter}
              placeholder="Filter by role"
            />
          </div>
        </div>
      </div>
      <div className="p-4 md:p-6">
        <div className="space-y-3">
          {filteredUsers?.map((user) => (
            <div
              key={user?.id}
              className="flex flex-col sm:flex-row sm:items-center gap-4 p-4 rounded-xl border border-border hover:bg-muted/30 transition-colors"
            >
              <div className="flex items-center gap-4 flex-1 min-w-0">
                <Image
                  src={user?.avatar}
                  alt={user?.avatarAlt}
                  className="w-12 h-12 rounded-full object-cover flex-shrink-0"
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1 flex-wrap">
                    <h4 className="font-bold text-foreground line-clamp-1">{user?.name}</h4>
                    {getRoleBadge(user?.role)}
                  </div>
                  <p className="text-sm text-muted-foreground line-clamp-1 truncate">{user?.email}</p>
                </div>
              </div>

              <div className="flex flex-row sm:flex-col lg:flex-row items-center justify-between sm:justify-center gap-4 pt-3 sm:pt-0 border-t sm:border-0 border-border/50">
                <div className="flex flex-col sm:items-end text-xs text-muted-foreground">
                  <div className="flex items-center gap-2 sm:justify-end">
                    <Icon name="Calendar" size={12} />
                    <span>{user?.joinedDate}</span>
                  </div>
                  <div className="flex items-center gap-2 mt-1 font-medium text-primary/80">
                    <Icon name="Award" size={12} />
                    <span>{user?.contributions} contributions</span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    iconName="Shield"
                    onClick={() => onUpdateRole(user?.id)}
                    title="Change Role"
                  />
                  <Button
                    variant="ghost"
                    size="sm"
                    iconName={user?.suspended ? 'UserCheck' : 'UserX'}
                    onClick={() => onSuspend(user?.id)}
                    title={user?.suspended ? 'Unsuspend' : 'Suspend'}
                  />
                  <Button
                    variant="ghost"
                    size="sm"
                    iconName="Trash2"
                    className="text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                    onClick={() => onDelete(user?.id)}
                    title="Delete User"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredUsers?.length === 0 && (
          <div className="text-center py-12">
            <Icon name="Users" size={48} color="var(--color-muted-foreground)" className="mx-auto mb-4" />
            <p className="text-muted-foreground">No users found matching your criteria</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserManagementPanel;