import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import PartnershipModal from '../../homepage/components/PartnershipModal';
import SubmitOpportunityModal from '../../homepage/components/SubmitOpportunityModal';

const CTASection = ({ data }) => {
  const navigate = useNavigate();
  const [isPartnershipModalOpen, setIsPartnershipModalOpen] = useState(false);
  const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
  if (!data) return null;

  const handleAction = (link, title, buttonText) => {
    // Robust check for WhatsApp links to ensure they always use the correct official link
    let finalLink = link;
    const isWhatsApp =
      title?.toLowerCase()?.includes('whatsapp') ||
      buttonText?.toLowerCase()?.includes('whatsapp') ||

      link?.toLowerCase()?.includes('wa.me') ||
      link?.toLowerCase()?.includes('whatsapp.com');

    if (isWhatsApp) {
      finalLink = 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V';
    }

    if (finalLink?.startsWith('http')) {
      window.open(finalLink, '_blank');
    } else if (finalLink === 'modal:partnership') {
      setIsPartnershipModalOpen(true);
    } else if (finalLink === 'modal:submission') {
      setIsSubmitModalOpen(true);
    } else if (finalLink) {
      navigate(finalLink);
    }
  };

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[var(--color-brand-blue)] text-white relative overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-10 right-10 w-64 h-64 bg-white rounded-full blur-3xl"></div>
        <div className="absolute bottom-10 left-10 w-96 h-96 bg-[var(--color-brand-purple)] rounded-full blur-3xl"></div>
      </div>
      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <h2 className="text-2xl md:text-3xl lg:text-5xl font-bold mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-white/90 max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {data.actions?.map((action, index) => (
            <div key={index} className="bg-white/10 backdrop-blur-sm rounded-2xl p-6 md:p-8 hover:bg-white/15 transition-all duration-300 group">
              <div className="w-14 h-14 md:w-16 md:h-16 rounded-xl bg-white/20 flex items-center justify-center mb-4 md:mb-6 group-hover:scale-110 transition-transform">
                <Icon name={action?.icon} size={28} color="#FFFFFF" />
              </div>

              <h3 className="text-xl md:text-2xl font-bold mb-3" style={{ fontFamily: 'var(--font-headline)' }}>
                {action?.title}
              </h3>

              <p className="text-sm md:text-base text-white/80 mb-6 leading-relaxed">
                {action?.description}
              </p>

              <Button
                variant="default"
                fullWidth
                onClick={() => handleAction(action.link, action.title, action.buttonText)}
                className="bg-white text-[#0f172a] hover:bg-white/90 font-bold border-none"
              >
                {action?.buttonText}
              </Button>
            </div>
          ))}
        </div>

        <div className="mt-12 md:mt-16 text-center">
          <div className="inline-flex flex-col sm:flex-row items-center gap-4 sm:gap-8 px-6 md:px-8 py-4 md:py-6 bg-white/10 backdrop-blur-sm rounded-2xl">
            {data.summaryStats?.map((s, idx) => (
              <div key={idx} className="flex items-center gap-3">
                <Icon name={s.icon} size={24} />
                <div className="text-left font-bold">
                  <div className="text-2xl md:text-3xl font-bold">{s.value}</div>
                  <div className="text-sm text-white/80">{s.label}</div>
                </div>
                {idx < data.summaryStats.length - 1 && <div className="hidden sm:block w-px h-12 bg-white/20 ml-4"></div>}
              </div>
            ))}
          </div>
        </div>
      </div>

      <PartnershipModal
        isOpen={isPartnershipModalOpen}
        onClose={() => setIsPartnershipModalOpen(false)}
      />
      <SubmitOpportunityModal
        isOpen={isSubmitModalOpen}
        onClose={() => setIsSubmitModalOpen(false)}
      />
    </section>
  );
};

export default CTASection;