import React from 'react';
import Icon from '../../../components/AppIcon';

const ContactHero = ({ data }) => {
  return (
    <section className="bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[var(--color-brand-blue)] text-white py-12 md:py-16 lg:py-20">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center max-w-3xl mx-auto">
          <div className="inline-flex items-center justify-center w-16 h-16 md:w-20 md:h-20 lg:w-24 lg:h-24 rounded-full bg-white/10 backdrop-blur-sm mb-6 md:mb-8">
            <Icon name="MessageCircle" size={32} className="md:w-10 md:h-10 lg:w-12 lg:h-12" />
          </div>
          <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data?.title || "Let's Connect & Build Together"}
          </h1>
          <p className="text-base md:text-lg lg:text-xl opacity-90 leading-relaxed">
            {data?.description || "Your success is our community's success. Whether you have questions, feedback, or want to contribute to our mission of democratizing opportunities, we're here to listen and support you every step of the way."}
          </p>
        </div>
      </div>
    </section>
  );
};

export default ContactHero;