import React from 'react';
import Icon from '../../../components/AppIcon';

const MissionSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-primary)]/10 rounded-full mb-4">
            <Icon name="Compass" size={20} color="var(--color-primary)" />
            <span className="text-sm font-medium text-[var(--color-primary)]">Our Mission</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {data.messages?.map((item, index) => (
            <div key={index} className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300">
              <div className="w-14 h-14 md:w-16 md:h-16 rounded-xl bg-gradient-to-br from-[var(--color-brand-blue)] to-[var(--color-brand-purple)] flex items-center justify-center mb-4 md:mb-6">
                <Icon name={item?.icon} size={28} color="#FFFFFF" />
              </div>
              <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-3" style={{ fontFamily: 'var(--font-headline)' }}>
                {item?.message}
              </h3>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                {item?.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default MissionSection;