import React, { useState } from 'react';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Button from '../../components/ui/Button';
import Icon from '../../components/AppIcon';
import Input from '../../components/ui/Input';
import { useToast } from '../../contexts/ToastContext';
import { cn } from '../../utils/cn';

const BuyCoffee = () => {
    const { addToast } = useToast();
    const [cupCount, setCupCount] = useState(1);
    const [name, setName] = useState('');
    const [message, setMessage] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    const cupPrice = 500; // ₦500 per coffee

    const handleSubmit = (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        // Integration Logic for Paystack
        const amountInKobo = cupCount * cupPrice * 100;
        const paystackPublicKey = 'pk_test_xxxxxxxxxxxxxxxxxxxxxxxx'; // User should replace with real key

        // Simulation of Paystack Popup Initialization
        setTimeout(() => {
            setIsSubmitting(false);

            // In a real environment, you would call:
            // const handler = window.PaystackPop.setup({
            //   key: paystackPublicKey,
            //   email: 'support@luc.com', // Replace with user email if collected
            //   amount: amountInKobo,
            //   onClose: () => addToast('Payment cancelled', 'info'),
            //   callback: (response) => {
            //      addToast(`Payment successful! Reference: ${response.reference}`, 'success');
            //   }
            // });
            // handler.openIframe();

            addToast(`Opening Paystack for ₦${(cupCount * cupPrice).toLocaleString()}...`, 'success');
        }, 1200);
    };

    return (
        <div className="min-h-screen bg-[#f8fafc] dark:bg-[#0a0f1a] flex flex-col transition-colors duration-300">
            <Helmet>
                <title>Buy LUC Hub a Coffee | Support Our Mission</title>
                <meta name="description" content="Support LUC Hub by buying us a coffee. Your support helps us keep the platform free and accessible for everyone." />
            </Helmet>

            <Header />

            <main className="flex-1 relative overflow-hidden">
                {/* Mesh Gradient Background inside main to allow header to be sticky relative to window */}
                <div className="absolute inset-0 pointer-events-none border-none">
                    <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-500/10 dark:bg-cyan-500/10 blur-[120px] rounded-full"></div>
                    <div className="absolute bottom-[10%] right-[-5%] w-[35%] h-[35%] bg-amber-500/10 dark:bg-amber-500/10 blur-[100px] rounded-full"></div>
                    <div className="absolute top-[20%] right-[10%] w-[30%] h-[30%] bg-blue-600/10 dark:bg-blue-600/5 blur-[120px] rounded-full"></div>
                </div>

                <div className="pb-10 md:pb-24 px-6 md:px-8 relative z-10">
                    <div className="max-w-4xl mx-auto flex flex-col">
                        {/* Header Spacer - Fixes the space between cup and header bar */}
                        <div className="h-28 md:h-20" />

                        <div className="text-center animate-in fade-in slide-in-from-bottom-4 duration-1000 px-2">
                            <div className="inline-flex items-center justify-center w-22 h-22 md:w-26 md:h-26 rounded-[2rem] bg-amber-100 dark:bg-amber-900/30 text-amber-600 mb-8 md:mb-10 shadow-2xl shadow-amber-500/10 rotate-3 hover:rotate-0 transition-transform duration-500">
                                <Icon name="Coffee" size={44} />
                            </div>
                            <h1 className="text-4xl md:text-6xl font-black text-slate-900 dark:text-white mb-6 md:mb-10 tracking-tight leading-[1.1]">
                                Fuel the <span className="text-amber-600">LUC</span> Mission
                            </h1>
                            <p className="text-lg md:text-xl text-slate-600 dark:text-slate-300 max-w-2xl mx-auto leading-relaxed">
                                LUC is a labor of love built to empower the community. Your "coffee" helps us keep the mission alive!
                            </p>
                        </div>

                        {/* Card Spacer - Fixes the space between text and card */}
                        <div className="h-32 md:h-28" />

                        <div className="flex flex-col lg:grid lg:grid-cols-12 gap-20 md:gap-24 items-start pb-20">
                            {/* Support Card */}
                            <div className="w-full max-w-[500px] lg:max-w-none mx-auto lg:col-span-7 bg-card rounded-[2.5rem] p-8 md:p-12 shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] dark:shadow-[0_32px_64px_-16px_rgba(0,0,0,0.5)] border border-border animate-in fade-in slide-in-from-left-6 duration-1000 delay-200">
                                <form onSubmit={handleSubmit} className="space-y-6 md:space-y-8">
                                    <div className="space-y-8">
                                        <div className="flex flex-wrap gap-4">
                                            {[1, 3, 5].map((num) => (
                                                <button
                                                    key={num}
                                                    type="button"
                                                    onClick={() => setCupCount(num)}
                                                    className={cn(
                                                        "flex-1 min-w-[80px] h-14 rounded-2xl border-2 font-black transition-all duration-500 flex items-center justify-center gap-2 group",
                                                        cupCount === num
                                                            ? "bg-amber-600 border-amber-600 text-white shadow-xl shadow-amber-500/20 scale-105"
                                                            : "bg-white dark:bg-slate-900 border-slate-200 dark:border-white/5 text-slate-600 dark:text-slate-400 hover:border-amber-500/30 hover:bg-slate-50 dark:hover:bg-slate-800"
                                                    )}
                                                >
                                                    <span className={cn(
                                                        "text-xl transition-transform duration-500",
                                                        cupCount === num ? "scale-110" : "group-hover:scale-110"
                                                    )}>☕</span>
                                                    <span className="text-lg">x{num}</span>
                                                </button>
                                            ))}
                                        </div>

                                        <div className="flex items-center gap-6 p-5 md:p-8 rounded-[2rem] bg-slate-100/90 dark:bg-slate-900/50 border-2 border-slate-200 dark:border-white/5 group hover:border-amber-500/30 transition-all duration-500 shadow-inner hover:shadow-amber-500/5">
                                            <div className="shrink-0 text-4xl md:text-5xl grayscale group-hover:grayscale-0 transition-all duration-700 hover:scale-110 cursor-default">☕</div>
                                            <div className="flex-1">
                                                <p className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em] mb-4 text-center">Or enter custom amount</p>
                                                <div className="flex flex-col gap-6 items-center justify-center">
                                                    <div className="relative group/input w-full max-w-[120px] md:max-w-[180px] mx-auto">
                                                        <div className="bg-slate-100 dark:!bg-slate-800/80 rounded-xl px-3 py-2 md:px-5 md:py-3 border-2 border-slate-200 dark:border-white/10 transition-all group-hover/input:border-amber-500/30">
                                                            <input
                                                                type="number"
                                                                min="1"
                                                                max="99999999"
                                                                value={cupCount}
                                                                onChange={(e) => setCupCount(Math.min(parseInt(e.target.value) || 1, 99999999))}
                                                                className="bg-transparent border-none focus:ring-0 font-black text-xl md:text-3xl text-slate-900 dark:!text-white w-full text-center transition-all appearance-none outline-none tabular-nums"
                                                                style={{ colorScheme: 'dark' }}
                                                            />
                                                        </div>
                                                        <div className="absolute bottom-0 left-0 w-full h-[2px] bg-amber-500/20 dark:bg-amber-500/20 group-hover/input:bg-amber-500 dark:group-hover/input:bg-amber-500 transition-colors"></div>
                                                    </div>

                                                    <div className="flex flex-col items-center justify-center text-center min-w-0 w-full overflow-hidden">
                                                        <span className="text-2xl md:text-4xl font-black text-amber-600 mb-1 leading-none break-all sm:break-normal">
                                                            ₦{(cupCount * cupPrice).toLocaleString()}
                                                        </span>
                                                        <span className="text-[9px] font-black text-slate-500 dark:text-slate-400 tracking-[0.2em] uppercase">Total Support</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="space-y-6">
                                        <div className="space-y-2">
                                            <label className="text-sm font-black text-slate-600 dark:text-slate-300 uppercase tracking-[0.2em]">
                                                Who are you?
                                            </label>
                                            <div className="bg-slate-100 dark:!bg-slate-800/80 rounded-2xl px-5 flex items-center h-14 border-2 border-slate-200 dark:border-white/5 transition-all focus-within:border-amber-500/30 shadow-inner">
                                                <input
                                                    placeholder="Name or handle (Optional)"
                                                    value={name}
                                                    onChange={(e) => setName(e.target.value)}
                                                    className="bg-transparent border-none focus:ring-0 w-full text-slate-900 dark:!text-white placeholder:text-slate-400 dark:placeholder:text-white/30 font-medium outline-none"
                                                />
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-black text-slate-600 dark:text-slate-300 uppercase tracking-[0.2em]">
                                                A little note
                                            </label>
                                            <div className="bg-slate-100 dark:!bg-slate-800/80 rounded-[1.5rem] px-5 py-4 border-2 border-slate-200 dark:border-white/5 transition-all focus-within:border-amber-500/30 shadow-inner">
                                                <textarea
                                                    placeholder="Say hi or share feedback..."
                                                    value={message}
                                                    onChange={(e) => setMessage(e.target.value)}
                                                    rows={4}
                                                    className="bg-transparent border-none focus:ring-0 w-full text-slate-900 dark:!text-white placeholder:text-slate-400 dark:placeholder:text-white/30 font-medium outline-none resize-none"
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex justify-center pt-2">
                                        <Button
                                            type="submit"
                                            variant="default"
                                            size="lg"
                                            loading={isSubmitting}
                                            className="h-12 md:h-14 px-8 md:px-10 w-auto rounded-xl md:rounded-2xl text-sm md:text-base font-bold shadow-lg shadow-amber-500/10 bg-amber-600 hover:bg-amber-700 hover:scale-[0.98] active:scale-95 transition-all border-none"
                                        >
                                            Support with ₦{(cupCount * cupPrice).toLocaleString()}
                                        </Button>
                                    </div>
                                </form>
                            </div>

                            {/* Impact Sidebar */}
                            <div className="w-full max-w-[500px] lg:max-w-none mx-auto lg:col-span-5 space-y-8 animate-in fade-in slide-in-from-right-6 duration-1000 delay-400">
                                <div className="bg-card rounded-[2.5rem] p-8 md:p-10 text-foreground shadow-2xl border border-border relative overflow-hidden group">
                                    <div className="absolute -top-10 -right-10 w-40 h-40 bg-amber-500/5 rounded-full blur-3xl group-hover:bg-amber-500/10 transition-all duration-700"></div>

                                    <h3 className="text-xl md:text-2xl font-black mb-8 flex items-center justify-center gap-3">
                                        <Icon name="ShieldCheck" size={26} className="text-amber-500" />
                                        The Impact
                                    </h3>

                                    <ul className="space-y-8">
                                        {[
                                            { title: 'Server Infrastructure', desc: 'Keep our discovery algorithms running fast and reliable 24/7.', icon: 'Server' },
                                            { title: 'Community Features', desc: 'Fund the development of matching and interactive tools.', icon: 'Users' },
                                            { title: 'Data Quality', desc: 'Allow us to source and verify the highest quality opportunities.', icon: 'Activity' }
                                        ].map((item, i) => (
                                            <li key={i} className="flex items-start group gap-8">
                                                <div className="shrink-0 w-12 h-12 rounded-2xl bg-muted flex items-center justify-center text-amber-500 shadow-lg transition-transform group-hover:scale-110">
                                                    <Icon name={item.icon} size={20} />
                                                </div>
                                                <div className="flex-1 min-w-0 pt-1">
                                                    <h4 className="font-bold text-lg mb-2 text-foreground leading-tight">{item.title}</h4>
                                                    <p className="text-sm text-muted-foreground leading-relaxed">{item.desc}</p>
                                                </div>
                                            </li>
                                        ))}
                                    </ul>
                                </div>

                                <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-2xl max-w-sm mx-auto w-full">
                                    <h4 className="font-black text-muted-foreground mb-6 uppercase tracking-widest text-[10px] text-center">Hall of Support</h4>
                                    <div className="space-y-6">
                                        {[
                                            { name: 'Alex Thompson', amount: 5, time: '2 hours ago', msg: 'Best tool for scholarships!' },
                                            { name: 'Sarah Chen', amount: 1, time: '5 hours ago', msg: 'Keep up the good work!' }
                                        ].map((s, i) => (
                                            <div key={i} className="flex items-start gap-8 group">
                                                <div className="w-10 h-10 shrink-0 rounded-xl bg-slate-100 dark:bg-white/5 flex items-center justify-center text-amber-500 font-black text-lg shadow-sm group-hover:scale-110 transition-transform">
                                                    {s.name[0]}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center justify-between mb-1 gap-2">
                                                        <p className="font-bold text-sm text-slate-800 dark:text-white truncate">{s.name}</p>
                                                        <span className="shrink-0 text-[9px] font-black uppercase text-slate-400 dark:text-white/40 tracking-wider font-mono">{s.time}</span>
                                                    </div>
                                                    <p className="text-[11px] text-slate-500 dark:text-white/60 italic line-clamp-2 leading-relaxed mb-2">"{s.msg}"</p>
                                                    <div className="flex gap-1 mt-1">
                                                        {Array(s.amount).fill('☕').map((c, i) => <span key={i} className="text-[10px] drop-shadow-sm">☕</span>)}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default BuyCoffee;
