import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { supabaseService } from '../../../services/supabaseService';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';

const ContactForm = () => {
  const { addToast } = useToast();
  const location = useLocation();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    inquiryType: '',
    subject: '',
    message: '',
    agreeToTerms: false
  });

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const type = params.get('type');
    if (type) {
      setFormData(prev => ({ ...prev, inquiryType: type }));
    }
  }, [location]);

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const inquiryTypes = [
    { value: 'general', label: 'General Inquiry' },
    { value: 'feedback', label: 'Feedback & Suggestions' },
    { value: 'volunteer', label: 'Volunteer Application' },
    { value: 'technical', label: 'Technical Support' },
    { value: 'other', label: 'Other' }
  ];

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.name?.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData?.email?.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/?.test(formData?.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (!formData?.inquiryType) {
      newErrors.inquiryType = 'Please select an inquiry type';
    }

    if (!formData?.subject?.trim()) {
      newErrors.subject = 'Subject is required';
    }

    if (!formData?.message?.trim()) {
      newErrors.message = 'Message is required';
    } else if (formData?.message?.trim()?.length < 20) {
      newErrors.message = 'Message must be at least 20 characters';
    }

    if (!formData?.agreeToTerms) {
      newErrors.agreeToTerms = 'You must agree to the terms';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleSubmit = async (e) => {
    e?.preventDefault();

    if (validateForm()) {
      setIsSubmitting(true);
      try {
        await supabaseService.submitContactMessage({
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          inquiry_type: formData.inquiryType,
          subject: formData.subject,
          message: formData.message,
          agreed_to_terms: formData.agreeToTerms
        });

        setIsSubmitting(false);
        setSubmitSuccess(true);
        setFormData({
          name: '',
          email: '',
          phone: '',
          inquiryType: '',
          subject: '',
          message: '',
          agreeToTerms: false
        });

        setTimeout(() => {
          setSubmitSuccess(false);
        }, 5000);
      } catch (error) {
        console.error('Submission error:', error);
        setIsSubmitting(false);
        addToast('Failed to send message. Please try again later.', 'error');
      }
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors?.[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-[var(--color-card)]">
      <div className="max-w-4xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12">
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            Send Us a Message
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            Have a specific question or proposal? Fill out the form below and our team will get back to you within 24 hours.
          </p>
        </div>

        {submitSuccess && (
          <div className="mb-6 md:mb-8 p-4 md:p-6 bg-[var(--color-success)]/10 border border-[var(--color-success)] rounded-xl flex items-start gap-3 md:gap-4">
            <Icon name="CheckCircle" size={24} color="var(--color-success)" className="flex-shrink-0 mt-1" />
            <div>
              <h4 className="font-semibold text-[var(--color-success)] mb-1 text-sm md:text-base">Message Sent Successfully!</h4>
              <p className="text-sm md:text-base text-[var(--color-foreground)]">
                Thank you for reaching out. We've received your message and will respond within 24 hours.
              </p>
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6 md:space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="Full Name"
              type="text"
              placeholder="Enter your full name"
              required
              value={formData?.name}
              onChange={(e) => handleChange('name', e?.target?.value)}
              error={errors?.name}
            />

            <Input
              label="Email Address"
              type="email"
              placeholder="your.email@example.com"
              required
              value={formData?.email}
              onChange={(e) => handleChange('email', e?.target?.value)}
              error={errors?.email}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="Phone Number"
              type="tel"
              placeholder="+1 (555) 123-4567"
              value={formData?.phone}
              onChange={(e) => handleChange('phone', e?.target?.value)}
              description="Optional - for urgent matters"
            />

            <Select
              label="Inquiry Type"
              placeholder="Select inquiry type"
              required
              options={inquiryTypes}
              value={formData?.inquiryType}
              onChange={(value) => handleChange('inquiryType', value)}
              error={errors?.inquiryType}
            />
          </div>

          <Input
            label="Subject"
            type="text"
            placeholder="Brief subject of your inquiry"
            required
            value={formData?.subject}
            onChange={(e) => handleChange('subject', e?.target?.value)}
            error={errors?.subject}
          />

          <div>
            <label className="block text-sm font-medium text-[var(--color-foreground)] mb-2">
              Message <span className="text-[var(--color-error)]">*</span>
            </label>
            <textarea
              rows={6}
              placeholder="Tell us more about your inquiry, feedback, or how you'd like to contribute to our community..."
              value={formData?.message}
              onChange={(e) => handleChange('message', e?.target?.value)}
              className="w-full px-4 py-3 rounded-lg border border-[var(--color-border)] bg-[var(--color-background)] text-[var(--color-foreground)] placeholder:text-[var(--color-muted-foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--color-ring)] transition-all duration-300 resize-none text-sm md:text-base"
            />
            {errors?.message && (
              <p className="mt-2 text-sm text-[var(--color-error)]">{errors?.message}</p>
            )}
            <p className="mt-2 text-xs md:text-sm text-[var(--color-muted-foreground)]">
              Minimum 20 characters required
            </p>
          </div>

          <Checkbox
            label="I agree to the terms and conditions and privacy policy"
            checked={formData?.agreeToTerms}
            onChange={(e) => handleChange('agreeToTerms', e?.target?.checked)}
            error={errors?.agreeToTerms}
            required
          />

          <div className="flex flex-col sm:flex-row gap-4 pt-4">
            <Button
              type="submit"
              variant="default"
              size="xl"
              loading={isSubmitting}
              iconName="Send"
              iconPosition="right"
              className="w-full sm:w-auto sm:min-w-[200px]"
            >
              {isSubmitting ? 'Sending...' : 'Send Message'}
            </Button>
            <Button
              type="button"
              variant="outline"
              size="xl"
              onClick={() => {
                setFormData({
                  name: '',
                  email: '',
                  phone: '',
                  inquiryType: '',
                  subject: '',
                  message: '',
                  agreeToTerms: false
                });
                setErrors({});
              }}
              className="w-full sm:w-auto sm:min-w-[150px]"
            >
              Clear Form
            </Button>
          </div>
        </form>

        <div className="mt-8 md:mt-12 p-4 md:p-6 bg-[var(--color-muted)] rounded-xl">
          <div className="flex items-start gap-3 md:gap-4">
            <Icon name="Info" size={20} color="var(--color-brand-blue)" className="flex-shrink-0 mt-1" />
            <div>
              <h4 className="font-semibold text-[var(--color-primary)] mb-2 text-sm md:text-base">Response Time Commitment</h4>
              <p className="text-xs md:text-sm text-[var(--color-muted-foreground)] leading-relaxed">
                We typically respond to all inquiries within 24 hours during business days. For urgent matters, please call us directly or join our WhatsApp community for immediate assistance.
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactForm;