import React from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';

const TeamSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-16 md:py-20 lg:py-24 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-secondary)]/10 rounded-full mb-4">
            <Icon name="Users" size={20} color="var(--color-secondary)" />
            <span className="text-sm font-medium text-[var(--color-secondary)]">Our Team</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 md:gap-8">
          {data.members?.map((member, index) => (
            <div key={index} className="bg-[var(--color-card)] rounded-2xl overflow-hidden shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 group">
              <div className="relative h-64 md:h-72 overflow-hidden">
                <Image
                  src={member?.image}
                  alt={member?.imageAlt || member?.name}
                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-[var(--color-primary)] to-transparent opacity-60"></div>
                <div className="absolute bottom-4 left-4 right-4">
                  <h3 className="text-lg md:text-xl font-bold text-white mb-1" style={{ fontFamily: 'var(--font-headline)' }}>
                    {member?.name}
                  </h3>
                  <p className="text-sm text-white/90">{member?.role}</p>
                </div>
              </div>

              <div className="p-6">
                <p className="text-sm text-[var(--color-muted-foreground)] leading-relaxed mb-4">
                  {member?.bio}
                </p>

                <div className="flex items-center gap-3">
                  <a href={member?.linkedin} className="w-10 h-10 rounded-lg bg-[var(--color-muted)] flex items-center justify-center hover:bg-[var(--color-primary)] hover:text-white transition-colors">
                    <Icon name="Linkedin" size={18} />
                  </a>
                  <a href={member?.twitter} className="w-10 h-10 rounded-lg bg-[var(--color-muted)] flex items-center justify-center hover:bg-[var(--color-primary)] hover:text-white transition-colors">
                    <Icon name="Twitter" size={18} />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default TeamSection;