import React, { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';

const CategorySection = () => {
  const { allOpportunities, categories: dbCategories } = useSelector((state) => state.content);

  const liveCategories = useMemo(() => {
    // If we have categories from DB, use them but update counts
    // Otherwise fallback to defaults
    const baseCategories = dbCategories.length > 0 ? dbCategories : [
      { id: 1, name: "Scholarships", icon: "GraduationCap", color: "from-emerald-500 to-teal-500", description: "Fully-funded and partial scholarships for all levels" },
      { id: 2, name: "Internships", icon: "Briefcase", color: "from-orange-500 to-rose-500", description: "Summer and year-round internships across industries" },
      { id: 3, name: "Fellowships", icon: "Users2", color: "from-blue-600 to-indigo-600", description: "Prestigious leadership and research programs" },
      { id: 4, name: "Competitions", icon: "Trophy", color: "from-amber-400 to-orange-600", description: "Showcase your skills and win prizes" },
      { id: 5, name: "Jobs", icon: "Target", color: "from-purple-500 to-pink-500", description: "Entry-level and professional career opportunities" },
      { id: 6, name: "Conferences", icon: "Globe", color: "from-cyan-500 to-blue-500", description: "Global events and networking opportunities" }
    ];

    return baseCategories.map(cat => ({
      ...cat,
      count: (allOpportunities || []).filter(opp => {
        const oppCat = (opp.category || '').toLowerCase();
        const catName = (cat.name || '').toLowerCase();
        // Match if identical, or if one contains the other (handling singular/plural)
        return oppCat === catName ||
          oppCat.includes(catName.replace(/s$/, '')) ||
          catName.includes(oppCat.replace(/s$/, ''));
      }).length
    }));
  }, [allOpportunities, dbCategories]);

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12">
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-3 md:mb-4">
            Explore by Category
          </h2>
          <p className="text-sm md:text-base lg:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            Discover opportunities tailored to your goals across diverse categories
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
          {liveCategories?.map((category) => (
            <Link
              key={category?.id}
              to="/opportunity-discovery"
              className="group relative bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 hover:-translate-y-1 border border-[var(--color-border)]"
            >
              {category?.count > 5 && (
                <div className="absolute top-4 right-4 px-3 py-1 bg-[var(--color-accent)] text-white text-xs font-semibold rounded-full flex items-center gap-1">
                  <Icon name="TrendingUp" size={12} />
                  <span>Trending</span>
                </div>
              )}

              <div className={`w-14 h-14 md:w-16 md:h-16 rounded-xl bg-gradient-to-br ${category?.color} flex items-center justify-center mb-4 md:mb-6 group-hover:scale-110 transition-transform duration-300`}>
                <Icon name={category?.icon || 'Briefcase'} size={28} color="white" />
              </div>

              <h3 className="text-lg md:text-xl font-bold text-[var(--color-primary)] mb-2">
                {category?.name}
              </h3>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] mb-4">
                {category?.description}
              </p>

              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-[var(--color-secondary)]">
                  <Icon name="FileText" size={16} />
                  <span className="text-sm md:text-base font-semibold">{category?.count} opportunities</span>
                </div>
                <Icon name="ArrowRight" size={20} className="text-[var(--color-muted-foreground)] group-hover:text-[var(--color-secondary)] group-hover:translate-x-1 transition-all duration-300" />
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CategorySection;