import React from 'react';
import Icon from '../../../components/AppIcon';

const CommunityGuidelines = ({ data }) => {
  if (!data) return null;

  return (
    <section id="guidelines" className="py-16 md:py-20 lg:py-24 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-12 md:mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-success)]/10 rounded-full mb-4">
            <Icon name="BookOpen" size={20} color="var(--color-success)" />
            <span className="text-sm font-medium text-[var(--color-success)]">Community Guidelines</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            {data.title}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-3xl mx-auto">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8 mb-12 md:mb-16">
          {data.items?.map((guideline, index) => (
            <div key={index} className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300">
              <div className="flex items-start gap-4 mb-4 md:mb-6">
                <div className="w-12 h-12 md:w-14 md:h-14 rounded-xl bg-gradient-to-br from-[var(--color-brand-blue)] to-[var(--color-brand-purple)] flex items-center justify-center flex-shrink-0">
                  <Icon name={guideline?.icon} size={24} color="#FFFFFF" />
                </div>
                <div className="flex-1">
                  <h3 className="text-lg md:text-xl font-bold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                    {guideline?.title}
                  </h3>
                  <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                    {guideline?.description}
                  </p>
                </div>
              </div>

              <div className="space-y-3">
                {guideline?.rules?.map((rule, ruleIndex) => (
                  <div key={ruleIndex} className="flex items-start gap-3">
                    <div className="w-5 h-5 rounded-full bg-[var(--color-success)]/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                      <Icon name="Check" size={14} color="var(--color-success)" />
                    </div>
                    <p className="text-sm text-[var(--color-foreground)] leading-relaxed flex-1">
                      {rule}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="bg-gradient-to-br from-[var(--color-warning)]/10 to-[var(--color-error)]/10 rounded-2xl p-6 md:p-8 lg:p-10 border-2 border-[var(--color-warning)]/20">
          <div className="flex flex-col lg:flex-row items-start gap-6">
            <div className="w-16 h-16 md:w-20 md:h-20 rounded-xl bg-[var(--color-warning)] flex items-center justify-center flex-shrink-0">
              <Icon name="AlertCircle" size={36} color="#FFFFFF" />
            </div>
            <div className="flex-1">
              <h3 className="text-xl md:text-2xl font-bold text-[var(--color-primary)] mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
                {data.consequences?.title}
              </h3>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed mb-4">
                {data.consequences?.description}
              </p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {data.consequences?.levels?.map((lvl, idx) => (
                  <div key={idx} className="bg-[var(--color-card)] rounded-xl p-4">
                    <div className={`font-bold mb-2 ${lvl.type === 'error' ? 'text-[var(--color-error)]' : 'text-[var(--color-warning)]'}`}>
                      {lvl.title}
                    </div>
                    <p className="text-sm text-[var(--color-muted-foreground)]">{lvl.description}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default CommunityGuidelines;