import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  addOpportunityAsync,
  updateOpportunityAsync,
  deleteOpportunityAsync
} from '../../store/contentSlice';
import { supabaseService } from '../../services/supabaseService';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import UserProfileDropdown from '../../components/UserProfileDropdown';
import StatsCard from './components/StatsCard';
import QuickActionCard from './components/QuickActionCard';
import RecentActivityItem from './components/RecentActivityItem';
import OpportunityManagementTable from './components/OpportunityManagementTable';
import AnalyticsChart from './components/AnalyticsChart';
import UserManagementPanel from './components/UserManagementPanel';
import ContentManagement from './components/ContentManagement';
import OpportunityModal from './components/OpportunityModal';
import AboutManagement from './components/AboutManagement';
import ContactManagement from './components/ContactManagement';
import MessageManagement from './components/MessageManagement';
import PartnershipManagement from './components/PartnershipManagement';
import SubmissionManagement from './components/SubmissionManagement';
import AnalyticsManagement from './components/AnalyticsManagement';
import ConfirmationModal from '../../components/ui/ConfirmationModal';
import Button from '../../components/ui/Button';
import Icon from '../../components/AppIcon';
import { useToast } from '../../contexts/ToastContext';

const AdminDashboard = () => {
  const dispatch = useDispatch();
  const { addToast } = useToast();
  const [activeTab, setActiveTab] = useState('overview');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [editingOpportunity, setEditingOpportunity] = useState(null);
  const opportunities = useSelector((state) => state.content.allOpportunities);
  const [users, setUsers] = useState([]);
  const [isLoadingUsers, setIsLoadingUsers] = useState(false);
  const [savedItemsCount, setSavedItemsCount] = useState(0);
  const [opportunityGrowth, setOpportunityGrowth] = useState('0%');
  const [userGrowth, setUserGrowth] = useState('0%');
  const [savedGrowth, setSavedGrowth] = useState('0%');
  const [pendingPartnerships, setPendingPartnerships] = useState(0);
  const [pendingSubmissions, setPendingSubmissions] = useState(0);

  // Confirmation Modal State
  const [confirmConfig, setConfirmConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => { },
    type: 'danger'
  });

  useEffect(() => {
    const initDashboard = async () => {
      await fetchUsers();
      try {
        const savedItems = await supabaseService.getAllSavedOpportunities();
        setSavedItemsCount(savedItems.length);
        setSavedGrowth(calculateGrowth(savedItems));

        // Fetch pending counts
        const partnerships = await supabaseService.getPartnershipRequests();
        setPendingPartnerships(partnerships.filter(p => p.status === 'pending').length);

        const submissions = await supabaseService.getOpportunitySubmissions();
        setPendingSubmissions(submissions.filter(s => s.status === 'pending').length);
      } catch (error) {
        console.error("Error fetching dashboard data:", error);
      }
    };
    initDashboard();
  }, []);

  const calculateGrowth = (items, dateField = 'created_at') => {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));
    const sixtyDaysAgo = new Date(now.getTime() - (60 * 24 * 60 * 60 * 1000));

    const currentPeriod = items.filter(item => {
      const date = new Date(item[dateField]);
      return date >= thirtyDaysAgo && date <= now;
    }).length;

    const previousPeriod = items.filter(item => {
      const date = new Date(item[dateField]);
      return date >= sixtyDaysAgo && date < thirtyDaysAgo;
    }).length;

    if (previousPeriod === 0) return currentPeriod > 0 ? '+100%' : '0%';
    const growth = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
    return `${growth > 0 ? '+' : ''}${growth.toFixed(1)}%`;
  };

  const adminStats = useSelector((state) => state.content.stats);
  const aboutData = useSelector((state) => state.content.about);

  useEffect(() => {
    if (opportunities.length > 0) {
      setOpportunityGrowth(calculateGrowth(opportunities));
    }
  }, [opportunities]);

  // Auto-sync High Water Mark Stats (Live but never decrease)
  useEffect(() => {
    const syncLifetimeStats = async () => {
      if (!adminStats || !opportunities.length || !users.length) return;

      let statsChanged = false;
      const updatedStats = adminStats.map(stat => {
        const label = stat.label?.toLowerCase() || '';
        let liveVal = 0;

        if (label.includes('member') || label.includes('user')) liveVal = users.length;
        else if (label.includes('opp') || label.includes('listing')) liveVal = opportunities.length;
        else return stat;

        const currentAdminNum = parseInt(String(stat.value).replace(/[^0-9]/g, '')) || 0;
        if (liveVal > currentAdminNum) {
          statsChanged = true;
          return { ...stat, value: `${liveVal.toLocaleString()}+` };
        }
        return stat;
      });

      if (statsChanged) {
        try {
          await supabaseService.updateSiteContent('stats', updatedStats);
        } catch (e) {
          console.error("Failed to sync lifetime stats:", e);
        }
      }

      // Sync About Page Hero Stats too
      if (aboutData?.hero?.stats) {
        let aboutChanged = false;
        const updatedAboutHeroStats = aboutData.hero.stats.map(s => {
          const label = s.label?.toLowerCase() || '';
          let liveVal = 0;
          if (label.includes('member') || label.includes('user')) liveVal = users.length;
          else if (label.includes('opp') || label.includes('listing')) liveVal = opportunities.length;
          else return s;

          const currentVal = parseInt(String(s.value).replace(/[^0-9]/g, '')) || 0;
          if (liveVal > currentVal) {
            aboutChanged = true;
            return { ...s, value: `${liveVal.toLocaleString()}+` };
          }
          return s;
        });

        if (aboutChanged) {
          try {
            const updatedAbout = {
              ...aboutData,
              hero: { ...aboutData.hero, stats: updatedAboutHeroStats }
            };
            await supabaseService.updateSiteContent('about', updatedAbout);
          } catch (e) {
            console.error("Failed to sync about lifetime stats:", e);
          }
        }
      }
    };

    if (activeTab === 'overview' && users.length > 0 && opportunities.length > 0) {
      syncLifetimeStats();
    }
  }, [opportunities.length, users.length, adminStats, aboutData, activeTab]);

  const fetchUsers = async () => {
    setIsLoadingUsers(true);
    try {
      const profiles = await supabaseService.getProfiles();
      const mappedUsers = profiles.map(p => ({
        id: p.id,
        name: p.full_name || 'Anonymous User',
        email: p.email || 'No email provided',
        role: p.role || 'user',
        avatar: p.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(p.full_name || 'U')}&background=random`,
        avatarAlt: p.full_name || 'User Avatar',
        joinedDate: p.created_at ? new Date(p.created_at).toLocaleDateString() : 'Unknown',
        contributions: p.contributions_count || 0,
        suspended: p.suspended || false,
        created_at: p.created_at
      }));
      setUsers(mappedUsers);
      setUserGrowth(calculateGrowth(profiles));
    } catch (error) {
      console.error("Error fetching users:", error);
    } finally {
      setIsLoadingUsers(false);
    }
  };

  const handleUpdateRole = async (userId) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;

    const roles = ['user', 'contributor', 'moderator', 'admin'];
    const currentIndex = roles.indexOf(user.role);
    const nextRole = roles[(currentIndex + 1) % roles.length];

    setConfirmConfig({
      isOpen: true,
      title: 'Update User Role',
      message: `Change ${user.name}'s role to ${nextRole}?`,
      type: 'info',
      confirmText: 'Update Role',
      onConfirm: async () => {
        try {
          await supabaseService.updateProfileRole(userId, nextRole);
          setUsers(users.map(u => u.id === userId ? { ...u, role: nextRole } : u));
          addToast("Role updated successfully!", "success");
        } catch (error) {
          console.error("Error updating role:", error);
          addToast("Failed to update role", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleToggleSuspension = async (userId) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;

    const newSuspendedState = !user.suspended;
    const action = newSuspendedState ? 'suspend' : 'unsuspend';

    setConfirmConfig({
      isOpen: true,
      title: `${action.charAt(0).toUpperCase() + action.slice(1)} User`,
      message: `Are you sure you want to ${action} ${user.name}?`,
      type: newSuspendedState ? 'danger' : 'warning',
      confirmText: action.charAt(0).toUpperCase() + action.slice(1),
      onConfirm: async () => {
        try {
          await supabaseService.updateToggleProfileSuspension(userId, newSuspendedState);
          setUsers(users.map(u => u.id === userId ? { ...u, suspended: newSuspendedState } : u));
          addToast(`User ${action}ed successfully`, "success");
        } catch (error) {
          console.error(`Error ${action}ing user:`, error);
          addToast(`Failed to ${action} user`, "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const statsData = [
    {
      title: "Total Opportunities",
      value: opportunities.length.toLocaleString(),
      change: opportunityGrowth,
      changeType: opportunityGrowth.startsWith('+') ? "positive" : (opportunityGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Briefcase",
      iconBg: "bg-gradient-to-br from-secondary to-brand-blue"
    },
    {
      title: "Active Community Members",
      value: isLoadingUsers ? "..." : users.length.toLocaleString(),
      change: userGrowth,
      changeType: userGrowth.startsWith('+') ? "positive" : (userGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Users",
      iconBg: "bg-gradient-to-br from-success to-secondary"
    },
    {
      title: "Saved Items",
      value: savedItemsCount.toLocaleString(),
      change: savedGrowth,
      changeType: savedGrowth.startsWith('+') ? "positive" : (savedGrowth === '0%' ? 'neutral' : 'negative'),
      icon: "Heart",
      iconBg: "bg-gradient-to-br from-success to-accent"
    }
  ];

  const quickActions = [
    {
      title: "Add Opportunity",
      description: "Create a new listing",
      icon: "Plus",
      iconBg: "bg-gradient-to-br from-success to-secondary",
      onClick: () => {
        setActiveTab('opportunities');
        setEditingOpportunity(null);
        setIsModalOpen(true);
      }
    },
    {
      title: "Review Partnerships",
      description: "Manage new proposals",
      icon: "Handshake",
      iconBg: "bg-gradient-to-br from-brand-blue to-accent",
      onClick: () => setActiveTab('partnerships')
    },
    {
      title: "New Submissions",
      description: "Approve community posts",
      icon: "UploadCloud",
      iconBg: "bg-gradient-to-br from-secondary to-success",
      onClick: () => setActiveTab('submissions')
    }
  ];

  const handleEditOpportunity = (id) => {
    const opp = opportunities.find(o => o.id === id);
    if (opp) {
      setEditingOpportunity(opp);
      setIsModalOpen(true);
    }
  };

  const handleDeleteOpportunity = (id) => {
    setConfirmConfig({
      isOpen: true,
      title: 'Delete Opportunity',
      message: 'Are you sure you want to delete this opportunity? This action cannot be undone.',
      type: 'danger',
      confirmText: 'Delete',
      onConfirm: async () => {
        try {
          await dispatch(deleteOpportunityAsync(id)).unwrap();
          addToast("Opportunity deleted successfully", "success");
        } catch (error) {
          addToast("Failed to delete opportunity", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleToggleTrending = (id) => {
    const opp = opportunities.find(o => o.id === id);
    if (opp) {
      dispatch(updateOpportunityAsync({ ...opp, trending: !opp.trending }));
    }
  };

  const handlePromoteSubmission = (submission) => {
    // Helper to normalize categories to platform standards
    const normalizeCategory = (cat) => {
      const c = cat?.toLowerCase() || '';
      if (c.includes('scholarship')) return 'scholarships';
      if (c.includes('internship')) return 'internships';
      if (c.includes('fellowship')) return 'fellowships';
      if (c.includes('competition') || c.includes('contest')) return 'competitions';
      if (c.includes('workshop')) return 'workshops';
      if (c.includes('conference')) return 'conferences';
      if (c.includes('job')) return 'jobs';
      return 'scholarships'; // Default fallback
    };

    // Map submission data to opportunity format
    const mappedOpportunity = {
      title: submission.title,
      organization: submission.organization,
      category: normalizeCategory(submission.category),
      detailedDescription: submission.description,
      shortDescription: submission.description?.substring(0, 150) + '...',
      applicationLink: submission.application_link,
      deadline: submission.deadline,
      status: 'active',
      verified: true, // Community submissions are verified by admin before publishing
      // Metadata to help admin know this was a submission
      _fromSubmissionId: submission.id
    };

    setEditingOpportunity(mappedOpportunity);
    setIsModalOpen(true);
  };

  const handleModalSubmit = async (data) => {
    try {
      // Destructure to separate the internal tracking ID from data being sent to the DB
      const { _fromSubmissionId, ...opportunityData } = data;

      if (editingOpportunity && editingOpportunity.id) {
        await dispatch(updateOpportunityAsync({ ...editingOpportunity, ...opportunityData })).unwrap();
      } else {
        await dispatch(addOpportunityAsync({
          ...opportunityData,
          views: 0,
          applicants: 0,
          daysLeft: 30,
          created_at: new Date().toISOString()
        })).unwrap();

        // If this was promoted from a submission (either from data or current state), mark it as approved
        const submissionId = _fromSubmissionId || editingOpportunity?._fromSubmissionId;
        if (submissionId) {
          await supabaseService.updateSubmissionStatus(submissionId, 'approved');
          addToast("Submission marked as approved and published!", "success");
        }
      }
      setIsModalOpen(false);
      setEditingOpportunity(null);
      addToast("Opportunity saved successfully!", "success");
    } catch (error) {
      console.error("Failed to save opportunity:", error);
      addToast("Failed to save opportunity", "error");
    }
  };

  const openAddModal = () => {
    setEditingOpportunity(null);
    setIsModalOpen(true);
  };

  const handleDeleteUser = async (userId) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;

    setConfirmConfig({
      isOpen: true,
      title: 'Delete User Account',
      message: `Are you sure you want to delete ${user.name}? This action is permanent and will remove all their profile data. Access to Supabase Auth must be handled separately.`,
      type: 'danger',
      confirmText: 'Delete Permanently',
      onConfirm: async () => {
        try {
          await supabaseService.deleteProfile(userId);
          setUsers(users.filter(u => u.id !== userId));
          addToast("User profile deleted successfully", "success");
        } catch (error) {
          console.error("Error deleting user:", error);
          addToast("Failed to delete user profile", "error");
        }
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const tabs = [
    { id: 'overview', label: 'Overview', icon: 'LayoutDashboard' },
    { id: 'opportunities', label: 'Opportunities', icon: 'Briefcase' },
    { id: 'content', label: 'Homepage', icon: 'Home' },
    { id: 'about', label: 'About Page', icon: 'Info' },
    { id: 'contact', label: 'Contact Page', icon: 'MessageCircle' },
    { id: 'inbox', label: 'Inbox', icon: 'Mail' },
    { id: 'partnerships', label: 'Partnerships', icon: 'Handshake' },
    { id: 'submissions', label: 'Submissions', icon: 'UploadCloud' },
    { id: 'analytics', label: 'Analytics', icon: 'BarChart' },
    { id: 'users', label: 'Users', icon: 'Users' }
  ];

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <Header />

      {/* Dashboard Container */}
      <div className="flex-1 flex flex-col lg:flex-row">

        {/* Sidebar - Desktop */}
        {/* Mobile Sidebar Overlay */}
        {isSidebarOpen && (
          <div
            className="fixed inset-0 bg-black/50 z-30 lg:hidden backdrop-blur-sm"
            onClick={() => setIsSidebarOpen(false)}
            aria-hidden="true"
          />
        )}

        {/* Sidebar - Responsive (Drawer on Mobile, Sticky on Desktop) */}
        <aside className={`
          fixed lg:sticky top-16 left-0 z-40 h-[calc(100vh-64px)] flex flex-col w-72 bg-card border-r border-border transition-transform duration-300 ease-in-out
          ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0 lg:shadow-none'}
        `}>
          <div className="flex-1 py-8 px-4 space-y-2 overflow-y-auto">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id);
                  setIsSidebarOpen(false);
                }}
                className={`w-full flex items-center gap-3 px-4 py-3 font-semibold rounded-2xl transition-all duration-300 ${activeTab === tab.id
                  ? 'bg-primary text-primary-foreground shadow-lg shadow-primary/20 scale-[1.02]'
                  : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                  }`}
              >
                <div className={`p-1.5 rounded-lg ${activeTab === tab.id ? 'bg-white/20' : 'bg-muted'}`}>
                  <Icon name={tab.icon} size={20} />
                </div>
                <span className="flex-1 text-left">{tab.label}</span>

                {tab.id === 'partnerships' && pendingPartnerships > 0 && (
                  <span className="bg-brand-blue text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full animate-pulse">
                    {pendingPartnerships}
                  </span>
                )}

                {tab.id === 'submissions' && pendingSubmissions > 0 && (
                  <span className="bg-secondary text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full animate-pulse">
                    {pendingSubmissions}
                  </span>
                )}
              </button>
            ))}
          </div>

          <div className="p-4 border-t border-border">
            <div className="bg-primary/5 rounded-2xl p-4">
              <p className="text-xs font-bold text-primary mb-1 uppercase tracking-widest">Admin Access</p>
              <p className="text-[10px] text-muted-foreground leading-tight">You are currently in management mode. Changes made here affect the live platform.</p>
            </div>
          </div>
        </aside>

        {/* Mobile Nav - Horizontal Scroll or Bottom Bar */}
        {/* Mobile Nav Trigger */}
        <div className="lg:hidden sticky top-16 z-30 bg-card border-b border-border shadow-sm px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="p-2 -ml-2 text-muted-foreground hover:bg-muted hover:text-foreground rounded-lg transition-colors"
              aria-label="Open sidebar"
            >
              <Icon name="Menu" size={24} />
            </button>
            <span className="font-bold text-lg">{tabs.find(t => t.id === activeTab)?.label}</span>
          </div>
        </div>

        {/* Main Content Area */}
        <main className="flex-1 overflow-x-hidden">
          <div className="max-w-7xl mx-auto px-4 lg:px-8 py-6 md:py-10">
            {/* Context Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <div>
                <h1 className="text-3xl font-black text-primary tracking-tight">
                  {tabs.find(t => t.id === activeTab)?.label}
                </h1>
                <p className="text-muted-foreground">
                  {activeTab === 'overview' && 'Manage your community platform at a glance'}
                  {activeTab === 'opportunities' && 'Create, edit and manage opportunity listings'}
                  {activeTab === 'content' && 'Update the main homepage sections'}
                  {activeTab === 'users' && 'Manage community members and roles'}
                  {activeTab === 'inbox' && 'View and respond to community messages'}
                  {activeTab === 'partnerships' && 'Review and manage organizational partnership requests'}
                  {activeTab === 'submissions' && 'Review opportunities submitted by community members'}
                  {/* Default text for others */}
                  {!['overview', 'opportunities', 'content', 'users', 'inbox', 'partnerships', 'submissions'].includes(activeTab) && `Manage current ${activeTab} settings`}
                </p>
              </div>

              {activeTab === 'opportunities' && (
                <Button
                  variant="default"
                  iconName="Plus"
                  onClick={openAddModal}
                  size="lg"
                  className="shadow-xl"
                >
                  Add Opportunity
                </Button>
              )}
            </div>

            {/* Content Switcher */}
            <div className="min-h-[60vh]">
              {activeTab === 'overview' && (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {statsData.map((stat, i) => <StatsCard key={i} {...stat} />)}
                  </div>
                  <div className="max-w-md">
                    <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                      <Icon name="Zap" size={20} className="text-secondary" />
                      Quick Actions
                    </h2>
                    <div className="grid grid-cols-1 gap-4">
                      {quickActions.map((action, i) => <QuickActionCard key={i} {...action} />)}
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'opportunities' && (
                <div className="animate-in fade-in duration-500">
                  <OpportunityManagementTable
                    opportunities={opportunities}
                    onEdit={handleEditOpportunity}
                    onDelete={handleDeleteOpportunity}
                    onToggleTrending={handleToggleTrending}
                    onBulkAction={() => { }}
                  />
                </div>
              )}

              {activeTab === 'content' && <div className="animate-in fade-in duration-500"><ContentManagement /></div>}
              {activeTab === 'about' && <div className="animate-in fade-in duration-500"><AboutManagement /></div>}
              {activeTab === 'contact' && <div className="animate-in fade-in duration-500"><ContactManagement /></div>}
              {activeTab === 'inbox' && <div className="animate-in fade-in duration-500"><MessageManagement /></div>}
              {activeTab === 'partnerships' && <div className="animate-in fade-in duration-500"><PartnershipManagement /></div>}
              {activeTab === 'submissions' && (
                <div className="animate-in fade-in duration-500">
                  <SubmissionManagement onPublish={handlePromoteSubmission} />
                </div>
              )}
              {activeTab === 'analytics' && <div className="animate-in fade-in duration-500"><AnalyticsManagement /></div>}

              {activeTab === 'users' && (
                <div className="animate-in fade-in duration-500">
                  <UserManagementPanel
                    users={users}
                    onUpdateRole={handleUpdateRole}
                    onSuspend={handleToggleSuspension}
                    onDelete={handleDeleteUser}
                    onRefresh={fetchUsers}
                    isLoading={isLoadingUsers}
                  />
                </div>
              )}
            </div>
          </div>
        </main>
      </div>

      <footer className="py-6 border-t border-border mt-auto">
        <div className="max-w-7xl mx-auto px-4 lg:px-8 text-center font-medium">
          <p className="text-sm text-muted-foreground">
            © {new Date().getFullYear()} LUC Opportunities. Empowering dreams through community-driven discovery.
          </p>
        </div>
      </footer>

      <OpportunityModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setEditingOpportunity(null);
        }}
        onSubmit={handleModalSubmit}
        initialData={editingOpportunity}
      />

      <ConfirmationModal
        isOpen={confirmConfig.isOpen}
        onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
        onConfirm={confirmConfig.onConfirm}
        title={confirmConfig.title}
        message={confirmConfig.message}
        type={confirmConfig.type}
        confirmText={confirmConfig.confirmText}
      />
    </div>
  );
};

export default AdminDashboard;
