import React, { useEffect } from "react";
import { Provider, useDispatch } from "react-redux";
import Routes from "./Routes";
import { ThemeProvider } from "./contexts/ThemeContext";
import SessionWarningModal from "./components/ui/SessionWarningModal";
import ScrollToTopButton from "./components/ui/ScrollToTopButton";
import store from "./store/store";
import { fetchAllContent } from "./store/contentSlice";

import { ToastProvider } from "./contexts/ToastContext";

const AppContent = () => {
  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(fetchAllContent());

    // Silent Refresh: Re-fetch content every 2 minutes
    // This keeps data fresh and ensures Supabase stays awake
    const intervalId = setInterval(() => {
      dispatch(fetchAllContent());
    }, 2 * 60 * 1000);

    return () => clearInterval(intervalId);
  }, [dispatch]);

  return <Routes />;
};

function App() {
  return (
    <Provider store={store}>
      <ThemeProvider>
        <ToastProvider>
          <AppContent />
        </ToastProvider>
      </ThemeProvider>
    </Provider>
  );
}

export default App;
