import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const HeroSection = () => {
  const { title, subtitle, primaryCTA, secondaryCTA, secondaryLink } = useSelector((state) => state.content.hero);
  const dbStats = useSelector((state) => state.content.stats);
  const [liveCounts, setLiveCounts] = useState({ members: 0, opportunities: 0, likes: 0, loading: true });

  useEffect(() => {
    const fetchCounts = async () => {
      try {
        const [profiles, opportunities] = await Promise.all([
          supabaseService.getProfiles(),
          supabaseService.getOpportunities()
        ]);
        const totalLikes = opportunities.reduce((acc, curr) => acc + (curr.likes_count || 0), 0);
        setLiveCounts({
          members: profiles.length,
          opportunities: opportunities.length,
          likes: totalLikes,
          loading: false
        });
      } catch (error) {
        console.error("Error fetching live counts:", error);
      }
    };
    fetchCounts();

    // Set up Realtime Subscription
    const usersChannel = supabaseService.subscribeToTable('profiles', (payload) => {
      if (payload.eventType === 'INSERT') setLiveCounts(prev => ({ ...prev, members: prev.members + 1 }));
      if (payload.eventType === 'DELETE') setLiveCounts(prev => ({ ...prev, members: Math.max(0, prev.members - 1) }));
    });

    const oppsChannel = supabaseService.subscribeToTable('opportunities', (payload) => {
      if (payload.eventType === 'INSERT') setLiveCounts(prev => ({ ...prev, opportunities: prev.opportunities + 1 }));
      if (payload.eventType === 'DELETE') setLiveCounts(prev => ({ ...prev, opportunities: Math.max(0, prev.opportunities - 1) }));
    });

    return () => {
      supabaseService.unsubscribe(usersChannel);
      supabaseService.unsubscribe(oppsChannel);
    };
  }, []);

  const stats = [
    { label: "Active Opportunities", value: liveCounts.loading ? "..." : (liveCounts.opportunities).toLocaleString() + "+" },
    { label: "Community Members", value: liveCounts.loading ? "..." : (liveCounts.members).toLocaleString() + "+" },
    { label: "Loves Received", value: liveCounts.loading ? "..." : (liveCounts.likes).toLocaleString() + "+" }
  ];

  return (
    <section className="relative bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[var(--color-brand-blue)] text-white overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-20 left-10 w-72 h-72 bg-[var(--color-accent)] rounded-full blur-3xl"></div>
        <div className="absolute bottom-20 right-10 w-96 h-96 bg-[var(--color-brand-purple)] rounded-full blur-3xl"></div>
      </div>
      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-16 md:py-24 lg:py-32">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 items-center">
          <div className="text-center lg:text-left">
            <div className="inline-flex items-center gap-1.5 md:gap-2 px-3 md:px-4 py-1.5 md:py-2 bg-white/10 backdrop-blur-sm rounded-full mb-6 md:mb-8 max-w-[90%] mx-auto lg:mx-0">
              <Icon name="Shield" size={16} className="md:w-5 md:h-5" />
              <span className="text-[11px] sm:text-sm md:text-base font-medium truncate">
                Trusted by {liveCounts.loading ? "..." : (liveCounts.members).toLocaleString()}+ Members
              </span>
            </div>
            <h1 className="text-3xl md:text-4xl lg:text-5xl xl:text-6xl font-bold mb-4 md:mb-6 leading-tight">
              {title}
            </h1>

            <p className="text-base md:text-lg lg:text-xl text-white/90 mb-6 md:mb-8 max-w-2xl mx-auto lg:mx-0">
              {subtitle}
            </p>

            <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
              <Button
                variant="default"
                size="lg"
                iconName="Search"
                iconPosition="left"
                className="bg-[var(--color-success)] hover:bg-[#229954] text-white shadow-lg"
                asChild
              >
                <Link to="/opportunity-discovery">{primaryCTA}</Link>
              </Button>

              <Button
                variant="outline"
                size="lg"
                iconName="MessageCircle"
                iconPosition="left"
                className="bg-white/10 backdrop-blur-sm border-white/30 text-white hover:bg-white/20"
                onClick={() => window.open(secondaryLink || 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V', '_blank')}
              >
                {secondaryCTA}
              </Button>
            </div>

            <div className="flex flex-wrap items-center justify-center lg:justify-start gap-6 md:gap-8 mt-8 md:mt-12">
              {stats?.map((stat, index) => (
                <div key={index} className="text-center lg:text-left">
                  <div className="text-2xl md:text-3xl font-bold text-[var(--color-accent)]">{stat?.value}</div>
                  <div className="text-sm md:text-base text-white/80">{stat?.label}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="hidden lg:block">
            <div className="relative">
              <div className="absolute inset-0 bg-gradient-to-br from-[var(--color-accent)]/20 to-[var(--color-brand-purple)]/20 rounded-3xl blur-2xl"></div>
              <div className="relative bg-white/10 backdrop-blur-lg rounded-3xl p-6 md:p-8 border border-white/20">
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-gradient-to-br from-[var(--color-accent)] to-[var(--color-warning)] flex items-center justify-center">
                    <Icon name="Award" size={24} color="white" />
                  </div>
                  <div>
                    <div className="text-lg md:text-xl font-semibold">Featured Today</div>
                    <div className="text-sm md:text-base text-white/80">Trending Opportunities</div>
                  </div>
                </div>

                <div className="space-y-4">
                  {[
                    { title: "Global Scholarship Program", deadline: "15 days left", type: "Scholarship" },
                    { title: "Tech Internship 2026", deadline: "30 days left", type: "Internship" },
                    { title: "Leadership Fellowship", deadline: "45 days left", type: "Fellowship" }
                  ]?.map((item, index) => (
                    <div key={index} className="bg-white/10 backdrop-blur-sm rounded-xl p-4 border border-white/10 hover:bg-white/20 transition-all duration-300 cursor-pointer">
                      <div className="flex items-start justify-between gap-3">
                        <div className="flex-1 min-w-0">
                          <h3 className="font-semibold text-sm md:text-base mb-1 line-clamp-1">{item?.title}</h3>
                          <div className="flex items-center gap-2 text-xs md:text-sm text-white/80">
                            <Icon name="Clock" size={14} />
                            <span className="whitespace-nowrap">{item?.deadline}</span>
                          </div>
                        </div>
                        <span className="px-3 py-1 bg-[var(--color-accent)]/20 rounded-full text-xs font-medium whitespace-nowrap">
                          {item?.type}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default HeroSection;