import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { updateHeroAsync, updateStatsAsync, updateCTAAsync } from '../../../store/contentSlice';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';

const ContentManagement = () => {
    const dispatch = useDispatch();
    const { addToast } = useToast();
    const hero = useSelector((state) => state.content.hero);
    const stats = useSelector((state) => state.content.stats);
    const cta = useSelector((state) => state.content.cta);

    const [heroForm, setHeroForm] = useState(hero);
    const [statsForm, setStatsForm] = useState(stats);

    const defaults = {
        whatsapp: {
            title: "Join Our WhatsApp Community",
            description: "Get instant notifications...",
            buttonText: "Join WhatsApp Channel",
            link: "https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V"
        },
        discovery: {
            title: "Start Your Discovery Journey",
            description: "Explore 2,500+ verified opportunities...",
            buttonText: "Explore Opportunities"
        },
        partner: {
            title: "Organizations & Institutions",
            description: "Reach 50,000+ ambitious students..."
        }
    };

    const [ctaForm, setCtaForm] = useState(cta || defaults);


    const handleHeroSubmit = (e) => {
        e.preventDefault();
        dispatch(updateHeroAsync(heroForm));
        addToast('Hero section updated on Supabase!', 'success');
    };

    const handleStatChange = (index, field, value) => {
        const newStats = [...statsForm];
        newStats[index] = { ...newStats[index], [field]: value };
        setStatsForm(newStats);
    };

    const handleStatsSubmit = (e) => {
        e.preventDefault();
        dispatch(updateStatsAsync(statsForm));
        addToast('Stats updated on Supabase!', 'success');
    };

    const handleCtaChange = (section, field, value) => {
        setCtaForm({
            ...ctaForm,
            [section]: {
                ...ctaForm[section],
                [field]: value
            }
        });
    };

    const handleCtaSubmit = (e) => {
        e.preventDefault();
        dispatch(updateCTAAsync(ctaForm));
        addToast('CTA section updated on Supabase!', 'success');
    };

    return (
        <div className="space-y-8 pb-20">
            {/* Hero Section Management */}
            <section className="bg-card rounded-2xl p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-primary/10 rounded-lg text-primary">
                        <Icon name="Layout" size={24} />
                    </div>
                    <h2 className="text-2xl font-bold">Manage Hero Section</h2>
                </div>

                <form onSubmit={handleHeroSubmit} className="space-y-4">
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">Headline</label>
                            <input
                                type="text"
                                value={heroForm?.title}
                                onChange={(e) => setHeroForm({ ...heroForm, title: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Subheadline</label>
                            <textarea
                                value={heroForm?.subtitle}
                                onChange={(e) => setHeroForm({ ...heroForm, subtitle: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none min-h-[100px]"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">WhatsApp Community Link</label>
                            <input
                                type="text"
                                value={heroForm?.secondaryLink || ''}
                                onChange={(e) => setHeroForm({ ...heroForm, secondaryLink: e.target.value })}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                            />
                        </div>
                    </div>
                    <Button type="submit" variant="default">Save Hero Changes</Button>
                </form>
            </section>

            {/* Community Stats Management */}
            <section className="bg-card rounded-2xl p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-accent/10 rounded-lg text-accent">
                        <Icon name="BarChart" size={24} />
                    </div>
                    <h2 className="text-2xl font-bold">Manage Community Stats</h2>
                </div>

                <form onSubmit={handleStatsSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {statsForm?.map((stat, index) => (
                            <div key={index} className="p-4 bg-muted rounded-xl border border-border space-y-3">
                                <div className="text-sm font-bold text-primary">Stat #{index + 1}</div>
                                <div>
                                    <label className="block text-xs font-medium mb-1">Label</label>
                                    <input
                                        type="text"
                                        value={stat?.label}
                                        onChange={(e) => handleStatChange(index, 'label', e.target.value)}
                                        className="w-full px-3 py-1 bg-background border border-border rounded-md text-sm"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-medium mb-1">Value</label>
                                    <input
                                        type="text"
                                        value={stat?.value}
                                        onChange={(e) => handleStatChange(index, 'value', e.target.value)}
                                        className="w-full px-3 py-1 bg-background border border-border rounded-md text-sm"
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                    <Button type="submit" variant="default">Update Stats</Button>
                </form>
            </section>

            {/* CTA Section Management */}
            <section className="bg-card rounded-2xl p-6 shadow-sm border border-border">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-brand-blue/10 rounded-lg text-brand-blue">
                        <Icon name="MessageCircle" size={24} />
                    </div>
                    <h2 className="text-2xl font-bold">Manage CTA Sections</h2>
                </div>

                <form onSubmit={handleCtaSubmit} className="space-y-8">
                    {/* WhatsApp Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">WhatsApp Community</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.title || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.whatsapp?.description || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Button Text</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.buttonText || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'buttonText', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Community Link (URL)</label>
                            <input
                                type="text"
                                value={ctaForm.whatsapp?.link || ''}
                                onChange={(e) => handleCtaChange('whatsapp', 'link', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                                placeholder="https://whatsapp.com/channel/..."
                            />
                        </div>
                    </div>

                    <div className="h-px bg-border my-6"></div>

                    {/* Discovery Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">Discovery Section</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.discovery?.title || ''}
                                onChange={(e) => handleCtaChange('discovery', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.discovery?.description || ''}
                                onChange={(e) => handleCtaChange('discovery', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Button Text</label>
                            <input
                                type="text"
                                value={ctaForm.discovery?.buttonText || ''}
                                onChange={(e) => handleCtaChange('discovery', 'buttonText', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                    </div>

                    <div className="h-px bg-border my-6"></div>

                    {/* Partner Section */}
                    <div className="space-y-4">
                        <h3 className="font-semibold text-lg">Partner Section</h3>
                        <div>
                            <label className="block text-sm font-medium mb-1">Title</label>
                            <input
                                type="text"
                                value={ctaForm.partner?.title || ''}
                                onChange={(e) => handleCtaChange('partner', 'title', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Description</label>
                            <textarea
                                value={ctaForm.partner?.description || ''}
                                onChange={(e) => handleCtaChange('partner', 'description', e.target.value)}
                                className="w-full px-4 py-2 bg-muted border border-border rounded-lg min-h-[80px]"
                            />
                        </div>
                    </div>

                    <Button type="submit" variant="default">Update CTA Sections</Button>
                </form>
            </section>
        </div>
    );
};

export default ContentManagement;
